#include "CloseToHSL/Core/Runtime/Domains/SecureCompute/Policies/Memory/YAKSys_Hybrid_CPU.Core.SecureMemoryAdmissionPolicy.h"
#include "CloseToHSL/Core/Runtime/Capabilities/Descriptors/YAKSys_Hybrid_CPU.Core.CapabilityDescriptorSet.h"
#include <cassert>
using namespace YAKSys_Hybrid_CPU::Core;
int main(){ auto epoch=std::make_shared<SecureRevocationEpoch>(7); auto region=std::make_shared<SecureMemoryRegionDescriptor>(SecureMemoryRegionClass::Shared,100,50,SecureMemoryHostVisibility::ExplicitShared,7); auto memory=std::make_shared<SecureMemoryDomainDescriptor>(1,2,epoch,std::vector{region},SecureMemoryDmaPolicy::ExplicitSharedBuffersWithTypedGrant); auto buffer=std::make_shared<SecureSharedBufferDescriptor>(); buffer->BufferId=3; buffer->Start=100; buffer->Length=20; buffer->Direction=SecureSharedBufferDirection::DomainToDevice; buffer->Grant={SecureGrantHandleKind::IoPolicy,1,2,7}; buffer->EvidenceClass=SecureEvidenceVisibilityClass::HostOwnedQuarantined; buffer->OwnerDomainTag=1; buffer->LifetimeEpoch=7; auto io=std::make_shared<SecureIoDomainDescriptor>(SecureIoDmaPolicy::ExplicitSharedBuffersOnly,std::vector{buffer},true); auto caps=std::make_shared<CapabilityDescriptorSet>(VmxV2InstructionCaps::VmCall,VmxV2InstructionCaps::VmCall,VmxV2InstructionCaps::VmCall); SecureMemoryAdmissionPolicy p; auto request=std::make_shared<SecureMemoryAccessRequest>(SecureMemoryAccessKind::RuntimeTouch,100,1); assert(p.Admit(memory,request)->IsAllowed); request->Kind=SecureMemoryAccessKind::HostRead; assert(p.Admit(memory,request)->IsAllowed); request->Kind=SecureMemoryAccessKind::Measurement; assert(p.Admit(memory,request)->Decision==SecureMemoryAdmissionDecision::DeniedMeasuredRegionMissing); auto dma=std::make_shared<SecureMemoryAccessRequest>(SecureMemoryAccessKind::DmaRead,100,1,SecureMemoryAccessOrigin::IoDma,CapabilityBoundaryRequirement(VmxV2InstructionCaps::VmCall,CapabilityGrantScope::CompatibilityProjection,true),caps); assert(p.Admit(memory,dma,io)->IsAllowed); dma->Kind=SecureMemoryAccessKind::DmaWrite; assert(p.Admit(memory,dma,io)->Decision==SecureMemoryAdmissionDecision::DeniedSharedBufferBinding); }
